// Controlled subprocess fixture, NOT Pi or AX acceptance.
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, unlinkSync } from 'node:fs';
import path from 'node:path';
let prompt = '';
for await (const chunk of process.stdin) prompt += chunk;
assert.equal(process.env.HOST_SENTINEL, undefined);
assert.equal(process.env.NODE_OPTIONS, undefined);
assert.equal(process.env.AX_TASK_YAML, undefined);
assert.equal(process.env.PI_OFFLINE, '1');
const settings = JSON.parse(readFileSync(path.join(process.env.PI_CODING_AGENT_DIR, 'settings.json'), 'utf8'));
assert.equal(settings.retry.enabled, false);
assert.equal(settings.retry.provider.maxRetries, 0);
assert.equal(settings.compaction.enabled, false);
for (const flag of ['--no-extensions', '--no-skills', '--no-session', '--no-prompt-templates', '--no-approve', '--mode']) assert.ok(process.argv.includes(flag));
assert.ok(process.argv.includes('fixture-provider'));
assert.ok(process.argv.includes('fixture-model'));
const event = (value) => process.stdout.write(JSON.stringify(value) + '\n');
event({ type: 'session', version: 3 });
event({ type: 'agent_start' });
event({ type: 'tool_execution_start', toolCallId: 'fixture-call', toolName: 'bash', args: { command: 'fixture-command (not executed)' } });
event({ type: 'tool_execution_end', toolCallId: 'fixture-call', toolName: 'bash', result: { content: [{ type: 'text', text: 'controlled fixture output' }] }, isError: true });
writeFileSync('fixture-started', 'yes');
writeFileSync('new.bin', Buffer.from([0, 255, 42]));
unlinkSync('delete.txt');
if (prompt === 'slow') await new Promise(() => { setInterval(() => {}, 1000); });
if (prompt === 'no-events') process.exit(0);
if (prompt === 'nonzero') process.exit(7);
if (prompt === 'invalid') process.stdout.write('not json\n');
if (prompt === 'retry') event({ type: 'auto_retry_start', attempt: 1 });
if (prompt === 'large-log') for (let i = 0; i < 80; i++) event({ type: 'message_update', text: 'x'.repeat(64 * 1024) });
if (prompt === 'long-record') process.stdout.write('x'.repeat(1024 * 1024 + 1) + '\n');
if (prompt === 'large-stderr') process.stderr.write('a'.repeat(5 * 1024 * 1024));
const secret = process.env.FIXTURE_TOKEN || 'none';
const message = JSON.stringify({ type: 'message_end', message: { role: 'assistant', stopReason: prompt === 'error-event' ? 'error' : prompt === 'length' ? 'length' : 'stop', content: [{ type: 'text', text: `fixture complete\u2028still one line ${secret}` }] } }) + '\n';
const messageBytes = Buffer.from(message);
const split = messageBytes.indexOf(Buffer.from('\u2028')) + 1; // Split inside a multibyte Unicode separator.
process.stdout.write(messageBytes.subarray(0, split));
await new Promise((resolve) => setTimeout(resolve, 5));
process.stdout.write(messageBytes.subarray(split));
process.stderr.write(`stderr ${secret.slice(0, 4)}`);
await new Promise((resolve) => setTimeout(resolve, 5));
process.stderr.write(`${secret.slice(4)}\n`);
event({ type: 'agent_end', willRetry: false, messages: [] });
if (prompt === 'unterminated') process.stdout.write(JSON.stringify({ type: 'agent_settled' }));
else event({ type: 'agent_settled' });
